WITH cte AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY store_id ORDER BY price DESC) mx,ROW_NUMBER() OVER(PARTITION BY store_id ORDER BY price) mn,COUNT(*) OVER(PARTITION BY store_id) cnt FROM inventory) SELECT s.store_id,s.store_name,s.location,mx.product_name AS most_exp_product,mn.product_name AS cheapest_product,ROUND(mn.quantity/mx.quantity,2) AS imbalance_ratio FROM stores s JOIN cte mx ON s.store_id=mx.store_id AND mx.mx=1 JOIN cte mn ON s.store_id=mn.store_id AND mn.mn=1 WHERE mx.cnt>=3 AND mx.quantity<mn.quantity ORDER BY imbalance_ratio DESC,s.store_name;